-- R01 B1 Short Functional Texts: revised Cambridge B1 Preliminary for Schools calibration
-- 30 original teacher-review items, informed by the uploaded book's description of short-text reading:
-- identify context and purpose, compare options carefully, and understand meaning rather than word-match.
-- No source questions or passages have been copied. Four options retained for EduAssess compatibility.
-- All items remain draft. Upsert preserves UUIDs and linked teacher review notes.
begin;
insert into public.reading_question_bank
(question_code,category,cefr_level,topic,skill,passage,prompt,options,correct_option,rationale,difficulty,estimated_seconds,status)
values
('B1-016','R01','B1','Education and Learning','Interpreting a request','DEBATE CLUB
We are preparing next week’s discussion on whether school uniforms should be compulsory. If you have a strong view, please send it to us, even if you cannot attend the meeting. We are particularly interested in examples from other schools.','Why is the club asking students to contact them?','[{"label":"A","text":"To collect opinions and supporting examples before the discussion."},{"label":"B","text":"To find students who can design a new school uniform."},{"label":"C","text":"To remind members that attendance at the meeting is compulsory."},{"label":"D","text":"To announce that the debate has been postponed."}]'::jsonb,'A','The request is for views and examples in advance; attendance is not required.','upper',60,'draft'),\n('B1-017','R01','B1','Travel and Transport','Understanding an exception','CITY BUS SERVICE
The weekend timetable will operate on Monday because of the public holiday. However, the first bus from the airport will leave at its usual weekday time. Passengers travelling from the airport should therefore check the normal Monday schedule.','What should airport passengers understand?','[{"label":"A","text":"Their service will follow the weekend timetable all day."},{"label":"B","text":"The first airport bus will run earlier than usual."},{"label":"C","text":"The holiday timetable does not apply to the first airport bus."},{"label":"D","text":"Airport services will not operate on Monday."}]'::jsonb,'C','The notice makes a specific exception for the first airport bus, which keeps its weekday departure time.','upper',65,'draft'),\n('B1-018','R01','B1','Technology and Society','Making an inference','PHOTO-SHARING SITE
You can remove a photograph from your profile at any time. This will stop it appearing on your page, but it may not remove copies that other users have already saved or shared. Think carefully before uploading images of other people.','What is the site warning users about?','[{"label":"A","text":"Deleting an image may not remove every copy of it."},{"label":"B","text":"Only photographs of friends can be uploaded."},{"label":"C","text":"Other users cannot share photographs from profiles."},{"label":"D","text":"Images disappear automatically after a short time."}]'::jsonb,'A','Removing a photograph from a profile does not guarantee that saved or shared copies disappear.','upper',65,'draft'),\n('B1-019','R01','B1','Community and Environment','Understanding eligibility','RIVER CLEAN-UP DAY
Local residents are invited to help clear litter from the river path on Saturday. Equipment will be provided, but volunteers should wear clothes they do not mind getting dirty. Under-16s may take part only when accompanied by an adult.','Who is able to volunteer?','[{"label":"A","text":"A 15-year-old arriving alone with their own equipment."},{"label":"B","text":"A visitor from another town who has no connection to the area."},{"label":"C","text":"A local 15-year-old coming with a parent."},{"label":"D","text":"A local adult who is unable to wear old clothes."}]'::jsonb,'C','The age condition is the key detail: under-16s must be accompanied by an adult.','upper',65,'draft'),\n('B1-020','R01','B1','Travel and Transport','Interpreting a restriction','TRAVEL CARD UPDATE
The Green Pass is now valid on all city buses and local trains. It cannot be used on airport express services, even when the journey begins within the city centre. Existing cardholders do not need to apply for a replacement.','Where can a Green Pass holder use the card?','[{"label":"A","text":"On any train leaving the city."},{"label":"B","text":"On the airport express if boarding downtown."},{"label":"C","text":"Only on buses travelling outside the city."},{"label":"D","text":"On local trains and city buses."}]'::jsonb,'D','The card covers local trains and city buses but excludes airport express services.','upper',65,'draft'),\n('B1-021','R01','B1','Work and Volunteering','Understanding suitability','WEEKEND INTERNSHIP
Our design studio is offering a two-day introduction for students interested in creative careers. Applicants do not need previous experience, but they should be comfortable working in a team and willing to explain their ideas. This is an observation opportunity rather than a paid job.','What is expected of applicants?','[{"label":"A","text":"They should already have worked in a design studio."},{"label":"B","text":"They should be ready to share and discuss their ideas."},{"label":"C","text":"They must be available for a paid position."},{"label":"D","text":"They should be able to work without other people."}]'::jsonb,'B','No experience is required; teamwork and explaining ideas are the stated expectations.','upper',65,'draft'),\n('B1-022','R01','B1','Consumer Information','Understanding a condition','ONLINE RETURNS
Items bought through our website can be returned by post within 14 days of delivery. Please use the returns label included in your parcel. Products purchased in one of our shops must be taken back to a shop and cannot be returned by post.','What should a customer do with an item bought in a shop?','[{"label":"A","text":"Take it to a shop to return it."},{"label":"B","text":"Send it to the website office using any label."},{"label":"C","text":"Contact the delivery company within 14 days."},{"label":"D","text":"Wait for a returns label to arrive by email."}]'::jsonb,'A','The policy distinguishes online purchases from shop purchases; shop items must be returned in person.','upper',65,'draft'),\n('B1-023','R01','B1','Arts and Culture','Interpreting purpose','MUSEUM LATE OPENING
On the first Thursday of each month, the museum stays open until 9 p.m. Visitors can explore the galleries as usual, but the guided tour is available only to people who book in advance. The café closes at its normal time.','What should visitors do if they want to join the tour?','[{"label":"A","text":"Arrive before the galleries open."},{"label":"B","text":"Book a place before visiting."},{"label":"C","text":"Visit on a different Thursday."},{"label":"D","text":"Ask the café staff to arrange it."}]'::jsonb,'B','The tour requires advance booking, although the museum itself remains open to all visitors.','upper',65,'draft'),\n('B1-024','R01','B1','Education and Learning','Recognising a change in arrangements','NOTICE TO COURSE PARTICIPANTS
Tomorrow’s photography session will take place outdoors if the weather remains dry. Please bring your camera as planned, but do not travel directly to the park. The instructor will confirm the meeting point by email this evening.','What do participants need to wait for?','[{"label":"A","text":"A decision about whether they should bring a camera."},{"label":"B","text":"An email confirming where to meet."},{"label":"C","text":"Permission to attend the photography course."},{"label":"D","text":"A new date for the session."}]'::jsonb,'B','The location is not yet confirmed; the instructor will email the meeting point.','upper',65,'draft'),\n('B1-025','R01','B1','Health and Lifestyle','Interpreting advice','RUNNING GROUP MESSAGE
Several members have asked whether they should run the full route at Saturday’s first session. There is no need to do so. The aim is to find a comfortable pace, and anyone who prefers to walk part of the way is welcome to do that.','What does the organiser want new members to do?','[{"label":"A","text":"Try to keep up with the fastest runners."},{"label":"B","text":"Complete the route without stopping."},{"label":"C","text":"Choose a pace that feels manageable."},{"label":"D","text":"Avoid joining unless they can run the whole distance."}]'::jsonb,'C','The message reassures members that the session is about finding a comfortable pace, not completing the route at speed.','upper',65,'draft'),\n('B1-026','R01','B1','Housing and Community','Understanding an implication','FLAT SHARE ADVERTISEMENT
The spare room is in a quiet flat shared by two postgraduate students. We are looking for someone who is happy to share cooking duties occasionally, although everyone usually prepares their own meals. The room is available immediately, but viewings are arranged after 6 p.m.','What would suit the people living in the flat?','[{"label":"A","text":"Someone who expects meals to be prepared for them."},{"label":"B","text":"Someone who is willing to help with cooking from time to time."},{"label":"C","text":"Someone who wants to share every meal with the others."},{"label":"D","text":"Someone who can only visit the flat during the day."}]'::jsonb,'B','The advert suggests occasional shared cooking, not regular communal meals.','upper',65,'draft'),\n('B1-027','R01','B1','Work and Communication','Understanding a polite refusal','EMAIL FROM THE PROJECT MANAGER
Thanks for offering to present the research findings on Friday. I think your summary would be useful, but the programme is already full. Could you send me the slides instead? I may be able to include one in the handout.','Why is the manager asking for the slides?','[{"label":"A","text":"The presentation has been moved to another day."},{"label":"B","text":"The manager does not think the research is useful."},{"label":"C","text":"There is no room for another presentation in the programme."},{"label":"D","text":"The speaker has not finished preparing the research."}]'::jsonb,'C','The programme is full, so the manager requests the slides as an alternative to a presentation.','upper',65,'draft'),\n('B1-028','R01','B1','Food and Hospitality','Understanding a qualification','RESTAURANT BOOKING POLICY
We can accommodate guests with food allergies, provided these are mentioned when the table is booked. Although our menu includes several vegetarian dishes, we cannot guarantee that every dish can be adapted for individual preferences on the evening.','What should a guest with a food allergy do?','[{"label":"A","text":"Mention it when making the reservation."},{"label":"B","text":"Choose a vegetarian dish after arriving."},{"label":"C","text":"Ask the waiter to change any dish on the menu."},{"label":"D","text":"Contact the restaurant only if a reaction occurs."}]'::jsonb,'A','The restaurant can accommodate allergies if informed at booking time.','upper',65,'draft'),\n('B1-029','R01','B1','Sport and Leisure','Understanding the main point','TENNIS CENTRE UPDATE
The outdoor courts are available again following maintenance. Members may notice that the surface feels slightly different at first; this is expected to improve grip. The indoor courts will remain open for anyone who has already booked them.','What are members being told?','[{"label":"A","text":"The outdoor courts have been permanently replaced."},{"label":"B","text":"The indoor courts are closed during maintenance."},{"label":"C","text":"The outdoor courts may feel different but are ready to use."},{"label":"D","text":"All existing indoor bookings have been cancelled."}]'::jsonb,'C','The courts have reopened; the changed surface is expected to provide better grip.','upper',65,'draft'),\n('B1-030','R01','B1','Technology and Society','Interpreting a limitation','CLOUD STORAGE NOTICE
Your account includes automatic backups while your device is connected to Wi-Fi. Photos and documents are included, but downloaded films are excluded because they can be added again from your library. Check that your backup has completed before replacing your device.','Which content is not included in the backup?','[{"label":"A","text":"Photographs stored on the device."},{"label":"B","text":"Documents saved by the user."},{"label":"C","text":"Films downloaded from the library."},{"label":"D","text":"Files backed up over Wi-Fi."}]'::jsonb,'C','Downloaded films are explicitly excluded from automatic backups.','upper',65,'draft'),\n('B1-031','R01','B1','Media and Youth','Understanding intention','MESSAGE FROM THE SCHOOL EDITOR
Thanks for sending your article about the sports festival. The information is useful, but readers who were not there may find it difficult to follow. Could you add a short introduction explaining what the event was and why it was organised?','What does the editor want the writer to do?','[{"label":"A","text":"Remove the details about the festival."},{"label":"B","text":"Add background information for readers."},{"label":"C","text":"Change the article into an interview."},{"label":"D","text":"Submit the article to a different magazine."}]'::jsonb,'B','The editor wants an introduction that helps readers understand the event.','upper',65,'draft'),\n('B1-032','R01','B1','Technology and Society','Understanding a limitation','APP UPDATE NOTICE
The new version lets you save lessons for offline use. Any lesson you have already opened will be available without an internet connection, but new lessons must be downloaded first. Your notes will continue to sync when you reconnect.','What can users do without internet access?','[{"label":"A","text":"Open lessons they have downloaded previously."},{"label":"B","text":"Access every lesson in the course catalogue."},{"label":"C","text":"Synchronise new notes immediately."},{"label":"D","text":"Download additional lessons while travelling."}]'::jsonb,'A','Offline access applies to lessons already opened/downloaded; new ones require a connection first.','upper',65,'draft'),\n('B1-033','R01','B1','Community and Environment','Interpreting purpose','COUNCIL SURVEY
We are reviewing the location of the Saturday market. Before making a decision, we would like to hear from residents and regular visitors, particularly those who use public transport. The survey is open to everyone, not just people who live nearby.','Who is the council especially interested in hearing from?','[{"label":"A","text":"People who sell goods at other markets."},{"label":"B","text":"Residents who never visit the market."},{"label":"C","text":"People who travel to the market by public transport."},{"label":"D","text":"Only people living on the market street."}]'::jsonb,'C','The council particularly highlights people who use public transport, while keeping the survey open to everyone.','upper',65,'draft'),\n('B1-034','R01','B1','Arts and Culture','Understanding a condition','MUSEUM VOLUNTEERS
Volunteers are needed to welcome school groups during weekday mornings. Previous museum experience is not essential, as training will be provided. However, applicants should be available for at least one morning each week throughout the school term.','What is required of volunteers?','[{"label":"A","text":"They must have worked in a museum before."},{"label":"B","text":"They must be free on weekday mornings regularly."},{"label":"C","text":"They must be able to work every school day."},{"label":"D","text":"They must organise their own training."}]'::jsonb,'B','Experience is not required, but regular weekday-morning availability is.','upper',65,'draft'),\n('B1-035','R01','B1','Education and Learning','Understanding contrast','STUDENT BLOG: REVISION HABITS
I used to make long lists of everything I needed to revise, then feel discouraged when I could not finish them. Now I choose just two priorities for each evening. I still have plenty to do, but starting feels much easier and I remember more.','What has changed in the student’s approach?','[{"label":"A","text":"They spend less time studying because they have fewer subjects."},{"label":"B","text":"They now decide which tasks matter most before they begin."},{"label":"C","text":"They no longer make plans for their revision."},{"label":"D","text":"They have stopped revising in the evenings."}]'::jsonb,'B','The student has moved from long lists to selecting two priorities, making it easier to start.','upper',65,'draft'),\n('B1-036','R01','B1','Food and Hospitality','Understanding an arrangement','COOKING COURSE EMAIL
We are pleased to confirm your place on the Saturday course. You will prepare a full meal in small groups, so please tell us beforehand if you have any dietary requirements. Ingredients and equipment are supplied; you only need to bring an apron.','What should participants do before the course?','[{"label":"A","text":"Bring ingredients for the meal."},{"label":"B","text":"Choose which group they want to join on arrival."},{"label":"C","text":"Inform the organiser about dietary needs."},{"label":"D","text":"Bring their own cooking equipment."}]'::jsonb,'C','The organiser asks participants to report dietary requirements in advance; equipment and ingredients are supplied.','upper',65,'draft'),\n('B1-037','R01','B1','Travel and Transport','Understanding a service update','RAIL SERVICE INFORMATION
Trains are running normally between Central and Northgate. Passengers travelling beyond Northgate should change to replacement buses, which leave from the station forecourt. Train tickets are accepted on these buses.','What should passengers going beyond Northgate do?','[{"label":"A","text":"Continue on the same train to their destination."},{"label":"B","text":"Use a replacement bus after Northgate."},{"label":"C","text":"Buy a separate ticket for the bus."},{"label":"D","text":"Leave the station and find a local taxi."}]'::jsonb,'B','The service update says passengers must change to replacement buses beyond Northgate, using their train tickets.','upper',65,'draft'),\n('B1-038','R01','B1','Housing and Community','Understanding a request','MESSAGE FROM THE BUILDING MANAGER
The fire alarm will be tested on Wednesday morning. You may hear it sounding more than once, but there is no need to leave the building during the test. Please keep the entrance clear so the engineers can bring in their equipment.','What are residents being asked to do?','[{"label":"A","text":"Stay away from the entrance during the test."},{"label":"B","text":"Leave the building whenever the alarm sounds."},{"label":"C","text":"Switch off the alarm in their flats."},{"label":"D","text":"Make sure the engineers have finished by Wednesday."}]'::jsonb,'A','Residents are told not to block the entrance; the alarm is a planned test and evacuation is not required.','upper',65,'draft'),\n('B1-039','R01','B1','Work and Volunteering','Interpreting a requirement','CHARITY SHOP NOTICE
We are looking for volunteers to help sort donations on Saturday mornings. You do not need retail experience, but you should be comfortable lifting boxes and be able to commit for at least six weeks. Tea and lunch are provided.','Which applicant best meets the notice?','[{"label":"A","text":"Someone who can help once but cannot lift boxes."},{"label":"B","text":"Someone with retail experience who is unavailable on Saturdays."},{"label":"C","text":"Someone who can volunteer regularly and manage the physical work."},{"label":"D","text":"Someone who wants a paid retail position."}]'::jsonb,'C','The role requires Saturday-morning commitment and the ability to lift boxes; retail experience is unnecessary.','upper',65,'draft'),\n('B1-040','R01','B1','Consumer Information','Understanding a policy','CONCERT TICKETS
Tickets may be transferred to another person, but the name on the booking must be updated before the doors open. Refunds are available only if the event is cancelled. If you cannot attend, please arrange a transfer rather than contacting the venue for a refund.','What should someone do if they can no longer attend?','[{"label":"A","text":"Ask the venue to refund the ticket."},{"label":"B","text":"Give the ticket to someone else and update the booking name in time."},{"label":"C","text":"Wait until after the concert to change the name."},{"label":"D","text":"Cancel the booking and buy a new ticket for a friend."}]'::jsonb,'B','The policy permits transfer with a name update, while refunds are limited to cancelled events.','upper',65,'draft'),\n('B1-041','R01','B1','Health and Lifestyle','Understanding advice and reason','PHARMACY INFORMATION
This medicine may make you feel sleepy, especially when you first begin taking it. If you are affected, avoid driving or using machinery. Do not stop taking it without speaking to a healthcare professional.','What is the main reason for the warning about driving?','[{"label":"A","text":"The medicine may affect alertness."},{"label":"B","text":"The medicine must be taken before driving."},{"label":"C","text":"Driving reduces the medicine’s effectiveness."},{"label":"D","text":"The medicine should only be used at work."}]'::jsonb,'A','The warning links possible sleepiness with avoiding activities that require alertness.','upper',65,'draft'),\n('B1-042','R01','B1','Arts and Culture','Understanding a change','THEATRE EMAIL
Due to an unexpected technical problem, tonight’s performance will begin 30 minutes later than advertised. The doors will still open at the usual time, and refreshments will be available while audiences wait. Anyone unable to stay may exchange their ticket for another date.','What has changed for tonight’s audience?','[{"label":"A","text":"The theatre will open later than planned."},{"label":"B","text":"The performance will start later, but the doors open as usual."},{"label":"C","text":"Refreshments will no longer be served."},{"label":"D","text":"All tickets have been moved to another date."}]'::jsonb,'B','Only the performance start time changes; doors open at the usual time.','upper',65,'draft'),\n('B1-043','R01','B1','Technology and Society','Making an inference','ONLINE CLASS MESSAGE
I have uploaded the recording of yesterday’s lesson for anyone who was unable to join us. It includes the discussion but not the group activity, as that depended on everyone being present at the same time. Please use the worksheet if you want to try the activity yourself.','What can students understand about the recording?','[{"label":"A","text":"It contains every part of the lesson, including the group task."},{"label":"B","text":"It replaces the need to complete the worksheet."},{"label":"C","text":"It is mainly intended for students who missed the live lesson."},{"label":"D","text":"It can only be watched during the original lesson time."}]'::jsonb,'C','The recording is provided for those absent, but the group activity is not included.','upper',65,'draft'),\n('B1-044','R01','B1','Sport and Leisure','Understanding a recommendation','CYCLING CLUB NEWS
The coastal route is still open, but recent work has left loose stones along part of the path. Experienced riders may continue if they take care. For Sunday’s beginner group, we recommend the canal route instead, which has a smoother surface.','Why is the canal route recommended to beginners?','[{"label":"A","text":"The coastal route is closed to all cyclists."},{"label":"B","text":"The canal route is more suitable for less experienced riders."},{"label":"C","text":"The beginner group is expected to ride faster."},{"label":"D","text":"The coastal route is longer than the canal route."}]'::jsonb,'B','The smoother canal surface is presented as the safer, more suitable choice for beginners.','upper',65,'draft'),\n('B1-045','R01','B1','Work and Communication','Interpreting a request','EMAIL FROM A TEAM LEADER
Your draft report is clear and the main findings are easy to follow. Before I send it to the client, could you check that the recommendations are supported by the examples in section three? I would rather delay sending it than include claims we cannot demonstrate.','What does the team leader want checked?','[{"label":"A","text":"Whether the report’s suggestions are justified by its evidence."},{"label":"B","text":"Whether section three should be removed from the report."},{"label":"C","text":"Whether the client has already read the draft."},{"label":"D","text":"Whether the report can be shortened before printing."}]'::jsonb,'A','The leader is concerned that the recommendations must be supported by examples in section three.','upper',65,'draft')
on conflict (question_code) do update set
 category=excluded.category,cefr_level=excluded.cefr_level,topic=excluded.topic,skill=excluded.skill,
 passage=excluded.passage,prompt=excluded.prompt,options=excluded.options,correct_option=excluded.correct_option,
 rationale=excluded.rationale,difficulty=excluded.difficulty,estimated_seconds=excluded.estimated_seconds,
 status='draft',updated_at=now();

-- Rebalance answer positions without changing the correct answer text.
do $
declare
  q record;
  desired_label text;
  correct_text text;
  distractors text[];
  rebuilt jsonb;
  label text;
  distractor_index integer;
begin
  for q in select id, question_code, options, correct_option
           from public.reading_question_bank
           where category='R01' and cefr_level='B1'
             and question_code between 'B1-016' and 'B1-045'
  loop
    desired_label := case q.question_code
    when 'B1-016' then 'A'
    when 'B1-017' then 'B'
    when 'B1-018' then 'C'
    when 'B1-019' then 'D'
    when 'B1-020' then 'A'
    when 'B1-021' then 'B'
    when 'B1-022' then 'C'
    when 'B1-023' then 'D'
    when 'B1-024' then 'A'
    when 'B1-025' then 'B'
    when 'B1-026' then 'C'
    when 'B1-027' then 'D'
    when 'B1-028' then 'A'
    when 'B1-029' then 'B'
    when 'B1-030' then 'C'
    when 'B1-031' then 'D'
    when 'B1-032' then 'A'
    when 'B1-033' then 'B'
    when 'B1-034' then 'C'
    when 'B1-035' then 'D'
    when 'B1-036' then 'A'
    when 'B1-037' then 'B'
    when 'B1-038' then 'C'
    when 'B1-039' then 'D'
    when 'B1-040' then 'A'
    when 'B1-041' then 'B'
    when 'B1-042' then 'C'
    when 'B1-043' then 'D'
    when 'B1-044' then 'A'
    when 'B1-045' then 'B'
    end;
    select max(e.value->>'text') filter (where e.value->>'label'=q.correct_option),
           array_agg(e.value->>'text' order by e.ordinality) filter (where e.value->>'label'<>q.correct_option)
      into correct_text, distractors
      from jsonb_array_elements(q.options) with ordinality as e(value, ordinality);
    rebuilt := '[]'::jsonb;
    distractor_index := 1;
    for label in select unnest(array['A','B','C','D'])
    loop
      if label=desired_label then
        rebuilt := rebuilt || jsonb_build_array(jsonb_build_object('label',label,'text',correct_text));
      else
        rebuilt := rebuilt || jsonb_build_array(jsonb_build_object('label',label,'text',distractors[distractor_index]));
        distractor_index := distractor_index + 1;
      end if;
    end loop;
    update public.reading_question_bank
       set options=rebuilt, correct_option=desired_label, updated_at=now()
     where id=q.id;
  end loop;
end $;

commit;
